$('#map-btn').onclick=openMap;
function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function polygon(points,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fill()}
function drawSky(r){let g=ctx.createLinearGradient(0,0,0,H);let night=dayTime<5.7||dayTime>19.5;let dusk=dayTime>17.5&&dayTime<20;let top=night?'#26384d':dusk?'#b87969':r.sky[0],bottom=night?'#728290':dusk?'#e4ad7e':r.sky[1];g.addColorStop(0,top);g.addColorStop(1,bottom);ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 if(night){for(let i=0;i<45;i++){let x=(i*173-camera*.035)%W;if(x<0)x+=W;let y=20+(i*79%Math.max(80,H*.36));ctx.fillStyle='#fff3c8';ctx.globalAlpha=.35+(Math.sin(frame*.01+i)*.15);ctx.fillRect(x,y,1.3,1.3)}ctx.globalAlpha=1}
 const sunX=W*.78,sunY=H*.18;ctx.fillStyle=night?'#dce4dd':'#f6d69a';ctx.globalAlpha=night?.55:.8;ctx.beginPath();ctx.arc(sunX,sunY,night?17:24,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
 // distant layered ridges
 for(let layer=0;layer<3;layer++){let base=H*(.49+layer*.075),off=camera*(.07+layer*.055);ctx.beginPath();ctx.moveTo(0,H);ctx.lineTo(0,base);for(let x=0;x<=W+20;x+=20){let wx=x+off;let y=base-Math.sin(wx*.003+layer*2)*22-Math.sin(wx*.009+layer)*13;if(regionAt(worldX).name.includes('MOUNTAIN'))y-=Math.max(0,Math.sin(wx*.0015+layer)*55);ctx.lineTo(x,y)}ctx.lineTo(W,H);ctx.closePath();ctx.fillStyle=layer===0?'#687c74':layer===1?'#596e62':r.accent;ctx.globalAlpha=.22+layer*.12;ctx.fill();ctx.globalAlpha=1}
 // clouds
 for(let i=0;i<7;i++){let x=(i*230-camera*.12)% (W+160);if(x<-100)x+=W+260;let y=H*(.16+(i%3)*.075);ctx.fillStyle='#f3eee0';ctx.globalAlpha=night?.08:raining?.26:.3;ctx.beginPath();ctx.ellipse(x,y,35,9,0,0,Math.PI*2);ctx.ellipse(x+20,y-5,26,12,0,0,Math.PI*2);ctx.ellipse(x+39,y,28,8,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
}
function drawTrees(){for(let wx=Math.floor(camera/105)*105;wx<camera+W+120;wx+=105){let x=wx-camera;if(x< -80)continue;let seed=Math.sin(wx*1.12)*.5+.5;let y=terrain(wx);if(seed>.12){let h=48+seed*62;ctx.fillStyle='#473e30';ctx.fillRect(x-4,y-h*.35,8,h*.35);for(let k=0;k<3;k++){let yy=y-h+k*h*.23;polygon([[x,yy-h*.28],[x-h*.23,yy+h*.1],[x+h*.24,yy+h*.1]],['#355b43','#3f694a','#4e7450'][k])}if(regionAt(wx).name.includes('SWAMP')){ctx.fillStyle='#4b4534';ctx.fillRect(x-5,y-12,9,12);ctx.beginPath();ctx.ellipse(x,y-27,19,24,0,0,Math.PI*2);ctx.fillStyle='#49604c';ctx.fill()}}}}
function drawBackgroundDetails(){const r=regionAt(worldX);for(const s of stations){let x=s.x-camera;if(x< -120||x>W+120)continue;let y=terrain(s.x);ctx.save();ctx.translate(x,y);ctx.fillStyle='#282c26';ctx.globalAlpha=.7;ctx.font='800 9px system-ui';ctx.textAlign='center';ctx.fillText(s.name.toUpperCase(),0,-102);ctx.globalAlpha=1;ctx.font='18px system-ui';ctx.fillStyle='#efe5c7';ctx.textAlign='center';ctx.fillText(s.icon,0,-82);
 if([1,7,10,16,20,22].includes(s.id)){rounded(-28,-72,56,48,3,'#765d43');ctx.fillStyle='#a88b62';ctx.fillRect(-21,-65,42,4);ctx.fillRect(-21,-50,42,4);polygon([[-33,-72],[0,-94],[34,-72]],'#4e483c');ctx.fillStyle='#f2ad5c';ctx.fillRect(16,-56,6,9)}else if(s.id===0||s.id===4){polygon([[-24,-8],[-24,-48],[0,-69],[25,-48],[25,-8]],'#866c4d');polygon([[-29,-47],[0,-75],[30,-47]],'#4d4334');ctx.fillStyle='#e6c998';ctx.fillRect(-13,-38,11,11);ctx.fillRect(5,-38,11,11)}else if(s.id===22){ctx.fillStyle='#434b48';ctx.fillRect(-4,-100,8,92);for(let k=0;k<3;k++){ctx.fillStyle='#766c57';ctx.fillRect(-75,-35-k*13,145,3)}ctx.strokeStyle='#c3ae7e';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-20,-8);ctx.lineTo(-20,-83);ctx.lineTo(24,-103);ctx.lineTo(24,-8);ctx.stroke();ctx.fillStyle='#8c7557';ctx.fillRect(-68,-8,140,8)}else{rounded(-27,-51,54,44,4,s.id%2?'#857451':'#73644c');ctx.fillStyle='#b9a67d';ctx.fillRect(-18,-42,14,13);ctx.fillRect(5,-42,14,13);ctx.fillStyle='#463e32';ctx.fillRect(-7,-25,14,18)}
 // station marker at reachable nearby locations
 if(Math.abs(worldX-s.x)<105){ctx.fillStyle='#f5a64a';ctx.globalAlpha=.9;ctx.beginPath();ctx.arc(0,-115+Math.sin(frame*.06)*4,3,0,7);ctx.fill();ctx.globalAlpha=1}
 ctx.restore()}
 if(r.name.includes('OIL')){for(let x=100;x<W;x+=310){let wx=x+camera;if(Math.floor(wx/310)%2){let y=terrain(wx);ctx.save();ctx.translate(x,y);ctx.strokeStyle='#343b35';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(0,-5);ctx.lineTo(0,-70);ctx.lineTo(26,-70);ctx.lineTo(26,-5);ctx.moveTo(-13,-58);ctx.lineTo(39,-58);ctx.moveTo(-8,-5);ctx.lineTo(34,-5);ctx.stroke();ctx.strokeStyle='#c39552';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-66);ctx.lineTo(25,-55);ctx.lineTo(50,-64);ctx.stroke();ctx.restore()}}}
}
function drawTerrain(){ctx.beginPath();ctx.moveTo(0,H);for(let x=0;x<=W+8;x+=8)ctx.lineTo(x,terrain(camera+x));ctx.lineTo(W,H);ctx.closePath();let r=regionAt(worldX);let g=ctx.createLinearGradient(0,H*.68,0,H);g.addColorStop(0,r.ground);g.addColorStop(.38,r.name.includes('SWAMP')?'#393f32':'#484235');g.addColorStop(1,'#262a24');ctx.fillStyle=g;ctx.fill();
 // grassy ground line
 ctx.strokeStyle=r.name.includes('SWAMP')?'#82906a':'#a08c62';ctx.lineWidth=4;ctx.beginPath();for(let x=0;x<=W;x+=8){let y=terrain(camera+x);if(x===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.stroke();
 // dirt strata
 ctx.globalAlpha=.13;for(let i=0;i<7;i++){ctx.strokeStyle=i%2?'#d4c095':'#191f1b';ctx.lineWidth=2;ctx.beginPath();for(let x=0;x<W;x+=36){let y=H*.83+i*20+Math.sin((x+camera)*.009+i)*6;if(x===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.stroke()}ctx.globalAlpha=1;
 // muddy puddles, rocks & grass tufts
 for(let wx=Math.floor(camera/65)*65;wx<camera+W+65;wx+=65){let q=Math.sin(wx*3.1)*.5+.5,x=wx-camera,y=terrain(wx);if(q>.75){ctx.fillStyle=raining?'#728982':'#554b3b';ctx.globalAlpha=raining?.82:.55;ctx.beginPath();ctx.ellipse(x,y+5,9+q*12,3,0,0,7);ctx.fill();ctx.globalAlpha=1}if(q<.35){for(let z=0;z<3;z++){ctx.strokeStyle='#9ca574';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(x+z*4,y);ctx.lineTo(x+z*3-2,y-5-q*5);ctx.stroke()}}}
}
function wheel(x,y,r){ctx.fillStyle='#222522';ctx.beginPath();ctx.arc(x,y,r,0,7);ctx.fill();ctx.strokeStyle='#4e534b';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#9a9a7f';ctx.beginPath();ctx.arc(x,y,r*.45,0,7);ctx.fill();ctx.strokeStyle='#d5c9a4';ctx.lineWidth=1.4;for(let i=0;i<6;i++){let a=i*Math.PI/3;ctx.beginPath();ctx.moveTo(x+Math.cos(a)*r*.18,y+Math.sin(a)*r*.18);ctx.lineTo(x+Math.cos(a)*r*.38,y+Math.sin(a)*r*.38);ctx.stroke()}ctx.fillStyle='#252a25';ctx.beginPath();ctx.arc(x,y,r*.13,0,7);ctx.fill()}
function drawTruck(){let x=W*.38,y=terrain(worldX)-20+truckY;let t=trucks[truckIndex],scale=Math.min(1.14,.91+truckIndex*.025),bodyW=110+Math.min(truckIndex,7)*7,bodyH=31+Math.min(truckIndex,5)*1.5;ctx.save();ctx.translate(x,y);ctx.rotate(tilt);ctx.scale(scale,scale);
 // shadows, cargo & suspension
 ctx.fillStyle='#151a18';ctx.globalAlpha=.42;ctx.beginPath();ctx.ellipse(6,23,bodyW*.62,8,0,0,7);ctx.fill();ctx.globalAlpha=1;
 let wheels=truckIndex>=2? (truckIndex>=11?4:3):2;let axleXs=wheels===2?[-31,34]:wheels===3?[-43,0,43]:[-48,-17,17,48];let wy=12+Math.max(0,truckY)*.15;
 for(const wx of axleXs){ctx.strokeStyle='#343e36';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(wx,0);ctx.lineTo(wx,wy-5);ctx.stroke();ctx.strokeStyle='#d8a95f';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(wx-4,2);ctx.lineTo(wx+4,wy-3);ctx.stroke();wheel(wx,wy,truckIndex>=7?12:10)}
 let cargoW=job?50:0;if(cargoW){rounded(-12,-bodyH-16,cargoW,15,2,job.cargo.includes('PLANK')?'#93673f':job.cargo.includes('ENGINE')?'#4c5852':'#aa8051');ctx.strokeStyle='#dfb36c';ctx.lineWidth=1;for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(-8+i*12,-bodyH-15);ctx.lineTo(-8+i*12,-bodyH-2);ctx.stroke()}}
 // chassis and body
 rounded(-bodyW*.48,-7,bodyW*.9,10,3,'#29312b');let bodyColor=['#b74f3c','#777c4a','#5a6c58','#c27838','#6e5347','#64704c','#4f695a','#957140','#79836c','#566e6e','#515b58','#6d685c'][truckIndex];
 rounded(-bodyW*.47,-bodyH,bodyW*.88,bodyH,5,bodyColor);ctx.fillStyle='#d7bd85';ctx.fillRect(-bodyW*.43,-bodyH+4,bodyW*.72,2);ctx.fillStyle='#242d29';ctx.fillRect(-bodyW*.47,-bodyH+bodyH*.72,bodyW*.88,4);
 // cabin
 let cabX=truckIndex===7||truckIndex>=9?bodyW*.1:-bodyW*.38;let cabW=truckIndex>=7?42:40;polygon([[cabX,-bodyH],[cabX+7,-bodyH-22],[cabX+cabW-5,-bodyH-22],[cabX+cabW,-bodyH+3]],'#39443d');polygon([[cabX+10,-bodyH-18],[cabX+cabW-9,-bodyH-18],[cabX+cabW-6,-bodyH+1],[cabX+6,-bodyH+1]],'#9fc0ba');ctx.strokeStyle='#d8cb9e';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(cabX+cabW*.55,-bodyH-18);ctx.lineTo(cabX+cabW*.55,-bodyH);ctx.stroke();rounded(cabX-2,-bodyH+2,cabW+4,5,2,'#d7bd85');
 // grill, bumper and lamps
 ctx.fillStyle='#d9c596';ctx.fillRect(-bodyW*.48+1,-bodyH+8,7,8);ctx.fillStyle='#252a27';ctx.fillRect(-bodyW*.48+8,-bodyH+8,11,13);ctx.strokeStyle='#979981';ctx.lineWidth=1;for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(-bodyW*.48+10,-bodyH+10+i*3);ctx.lineTo(-bodyW*.48+17,-bodyH+10+i*3);ctx.stroke()}ctx.fillStyle='#252b27';ctx.fillRect(-bodyW*.52,-3,bodyW*.98,6);ctx.fillStyle='#d18c4a';ctx.fillRect(-bodyW*.46,-bodyH+20,7,3);
 if(lightsOn){let lg=ctx.createLinearGradient(-bodyW*.48,0,-W*.28,-20);lg.addColorStop(0,'#ffe7ae55');lg.addColorStop(1,'#ffe7ae00');polygon([[-bodyW*.48,-bodyH+8],[-W*.28,-120],[-W*.28,55],[-bodyW*.48,-bodyH+16]],lg)}
 if(inventoryTrailer>=0){ctx.strokeStyle='#b9aa7d';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(bodyW*.42,-4);ctx.lineTo(bodyW*.68,2);ctx.stroke();wheel(bodyW*.83,12,8);ctx.fillStyle='#846d4c';ctx.fillRect(bodyW*.65,-12,bodyW*.4,13);ctx.fillStyle='#a99066';ctx.fillRect(bodyW*.68,-14,bodyW*.34,3)}
 ctx.restore();
 // little wind and dirt
 if(Math.abs(velocity)>2&&frame%5===0){for(let i=0;i<2;i++)particles.push({x:x-18,y:y+9,vx:-Math.random()*1.5,vy:-Math.random()*1.2,life:.7,r:2+Math.random()*3})}
}
